<script setup lang="ts">
/**
 * Small read-only label for status or category (`design/components/badge.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/badge.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Text as TextVNode, computed, isVNode } from 'vue'

import { Icon, type IconRole } from '@polymorph/vue'
import styles from '@polymorph/recipes/structure/badge.module.css'

export type BadgeTone = NonNullable<BadgeProps['tone']>

export type BadgeVariant = NonNullable<BadgeProps['variant']>

export interface BadgeProps {
  /**
   * A number drawn in the text's place. Past `max` it reads as `max` and a plus sign. Zero or
   * less draws nothing.
   */
  count?: number
  /**
   * A mark with no number, for "something is new". `children` names it to a screen reader;
   * without `children` it is hidden from assistive technology.
   */
  dot?: boolean
  /**
   * Leading and decorative; the text carries the meaning. Not drawn by a count or a dot.
   */
  icon?: IconRole
  /**
   * The largest count drawn as it is; default 99.
   */
  max?: number
  tone?: 'info' | 'warning' | 'success' | 'accent' | 'danger' | 'neutral'
  variant?: 'solid' | 'soft' | 'outline'
}

defineOptions({ name: 'Badge', inheritAttrs: false })

const props = withDefaults(defineProps<BadgeProps>(), {
  dot: false,
  max: 99,
  tone: 'neutral',
  variant: 'soft',
})
defineSlots<{ default?: (props: Record<string, never>) => unknown }>()
// The text the caller put in a slot: its text nodes, in order, without the elements'.
const slotText = (slot: ((...args: never[]) => unknown) | undefined): string => {
  const read = (nodes: unknown): string =>
    typeof nodes === 'string'
      ? nodes
      : Array.isArray(nodes)
        ? nodes.map(read).join('')
        : isVNode(nodes) && nodes.type === TextVNode
          ? read(nodes.children)
          : ''
  return read(slot?.())
}
const shown = computed(() =>
  props.count === undefined
    ? ''
    : props.count > props.max
      ? String(props.max) + '+'
      : String(props.count),
)
</script>

<template>
  <template v-if="count !== undefined">
    <span
      v-if="count > 0"
      :class="styles.badge"
      :data-variant="variant"
      :data-tone="tone"
      data-count=""
      data-member="badge"
    >
      {{ shown }}
    </span>
  </template>
  <span
    v-else-if="dot"
    :class="styles.badge"
    :data-variant="variant"
    :data-tone="tone"
    :aria-hidden="slotText($slots.default) === '' ? true : undefined"
    data-dot=""
    data-member="badge"
  >
    <span v-if="slotText($slots.default) !== ''" :class="styles.spoken">
      <slot />
    </span>
  </span>
  <span v-else :class="styles.badge" :data-variant="variant" :data-tone="tone" data-member="badge">
    <span v-if="icon !== undefined" :class="styles.glyph">
      <Icon :name="icon" size="sm" />
    </span>
    <slot />
  </span>
</template>
